  color: var(--color-sale);
}

.original-price {
  color: var(--color-subtle);
  font-weight: 800;
  text-decoration: line-through;
}

.article-grid {
  grid-template-columns: 1.35fr 1fr;
}

.article-card {
  display: grid;
  gap: 1rem;
  padding: 1rem;
}

.article-card-large {
  grid-row: span 2;
}

.article-card h3 a {
  color: var(--color-ink);
  text-decoration: none;
}

.article-card h3 a:hover {
  color: var(--color-primary-strong);
  text-decoration: underline;
  text-decoration-thickness: 0.14em;
  text-underline-offset: 0.2em;
}

.article-image {
  min-height: 11rem;
  border-radius: 1rem;
  background: var(--color-canvas-strong);
}

.article-card-large .article-image {
  min-height: 22rem;
}

.article-image-one {
  background:
    linear-gradient(135deg, transparent 34%, #ffffff 35% 38%, transparent 39%),
    linear-gradient(135deg, #d8c0a5, #1f4d46);
}

.article-image-two {
  background:
    radial-gradient(circle at 25% 35%, #ffffff 0 12%, transparent 13%),
    linear-gradient(135deg, #e8b08c, #f4e4d2);
}

.article-image-three {
  background:
    radial-gradient(circle at 70% 26%, #1f4d46 0 18%, transparent 19%),
    linear-gradient(135deg, #c8dfd7, #f1ede5);
}

.newsletter {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(18rem, 0.8fr);
  gap: 1.5rem;
  align-items: center;
  margin-block: clamp(3rem, 6vw, 5rem);
  border-radius: var(--radius-lg);
  padding: clamp(1.25rem, 4vw, 3rem);
  box-shadow: var(--shadow-sm);
}

.newsletter p {
  margin: 0.85rem 0 0;
  color: var(--color-muted);
}

.newsletter-form {
  display: grid;
  gap: 0.45rem;
}

.newsletter-form label {
  font-weight: 900;
}

.form-row {
  display: flex;
  gap: 0.65rem;
}

input {
  width: 100%;
  min-height: 3rem;
  min-width: 0;
  border: 2px solid var(--color-line);
  border-radius: 999px;
  background: var(--color-surface);
  color: var(--color-ink);
  padding: 0.7rem 1rem;
}

input[aria-invalid="true"] {
  border-color: var(--color-sale);
}

.form-help,
.form-error,
.form-success {
  min-height: 1.4rem;
  font-size: 0.92rem;
}

.form-error {
  color: var(--color-sale);
  font-weight: 800;
}

.form-success {
  color: var(--color-primary-strong);
  font-weight: 900;
}

.site-footer {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  border-top: 1px solid var(--color-line);
  padding: 2rem 0;
}

.site-footer p {
  max-width: 28rem;
  margin: 0.8rem 0 0;
  color: var(--color-muted);
}

.footer-links {
  flex-wrap: wrap;
  justify-content: end;
}

.footer-links a {
  padding: 0.4rem;
}

@media (max-width: 900px) {
  .nav {
    grid-template-columns: auto auto auto;
    justify-content: space-between;
  }

  .nav-toggle {
    display: inline-flex;
    align-items: center;
    gap: 0.55rem;
    min-height: 2.75rem;
    border: 1px solid var(--color-primary);
    border-radius: 999px;
    background: var(--color-surface);
    color: var(--color-primary-strong);
    padding: 0.55rem 0.85rem;
    font-weight: 900;
    cursor: pointer;
  }

  .nav-toggle-lines,
  .nav-toggle-lines::before,
  .nav-toggle-lines::after {
    display: block;
    width: 1.1rem;
    height: 2px;
    background: currentColor;
  }

  .nav-toggle-lines {
    position: relative;
  }

  .nav-toggle-lines::before,
  .nav-toggle-lines::after {
    position: absolute;
    left: 0;
    content: "";
  }

  .nav-toggle-lines::before {
    top: -0.38rem;
  }

  .nav-toggle-lines::after {
    top: 0.38rem;
  }

  .nav-list {
    position: absolute;
    top: 100%;
    right: 1rem;
    left: 1rem;
    display: none;
    flex-direction: column;
    align-items: stretch;
    border: 1px solid var(--color-line);
    border-radius: var(--radius-md);
    background: var(--color-surface);
    padding: 0.6rem;
    box-shadow: var(--shadow-sm);
  }

  .nav-list.is-open {
    display: flex;
  }

  .nav-list a {
    padding: 0.9rem 1rem;
  }

  .hero,
  .newsletter,
  .article-grid {
    grid-template-columns: 1fr;
  }

  .product-grid,
  .deal-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .article-card-large {
    grid-row: auto;
  }
}

@media (max-width: 620px) {
  .nav,
  .site-footer,
  main > section,
  .deals > * {
    width: min(calc(100% - 1rem), var(--max-width));
  }

  .nav {
    grid-template-columns: 1fr auto;
  }

  .cart-button {
    grid-column: 1 / -1;
    justify-self: stretch;
  }

  .brand {
    min-width: 0;
  }

  .brand span:last-child {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .hero {
    padding-top: 2rem;
  }

  .hero-actions,
  .form-row,
  .site-footer {
    flex-direction: column;
  }

  .button,
  .cart-button {
    width: 100%;
  }

  .section-heading {
    align-items: start;
    flex-direction: column;
  }

  .product-grid,
  .deal-grid {
    grid-template-columns: 1fr;
  }

  .hero-art {
    min-height: 18rem;
  }

  .site-footer,
  .footer-links {
    align-items: start;
    justify-content: start;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
  }
}

@media (forced-colors: active) {
  :root {
    --color-ink: CanvasText;
