    --color-surface: Canvas;
    --color-canvas: Canvas;
    --color-canvas-strong: Canvas;
    --color-line: ButtonBorder;
    --color-primary: ButtonText;
    --color-primary-strong: ButtonText;
    --color-primary-soft: Canvas;
    --color-accent: LinkText;
    --color-sale: Mark;
