    badge: "Save $14",
    art: "linear-gradient(135deg, #e9ece1 0%, #9aaf9f 100%)",
  },
  {
    name: "Textured Throw Blanket",
    description: "Oversized cotton throw with a breathable waffle weave.",
    price: "$72",
    originalPrice: "$96",
    badge: "Deal",
    art: "linear-gradient(135deg, #f4d0bb 0%, #9e5f45 100%)",
  },
];

const featuredContainer = document.querySelector("#featured-products");
const dealsContainer = document.querySelector("#deal-products");
const cartCount = document.querySelector("#cart-count");
const navToggle = document.querySelector(".nav-toggle");
const navList = document.querySelector("#primary-menu");
const newsletterForm = document.querySelector("#newsletter-form");
const emailInput = document.querySelector("#email");
const emailError = document.querySelector("#email-error");
const formSuccess = document.querySelector("#form-success");

let cartItems = 0;

function productCardTemplate(product, index) {
  return `
    <article class="product-card">
      <div class="product-art" style="--product-bg: ${product.art}" aria-hidden="true"></div>
      <div class="product-content">
        <span class="product-badge">${product.badge}</span>
        <h3>${product.name}</h3>
        <p>${product.description}</p>
        <div class="product-meta">
          <span class="price">${product.price}</span>
        </div>
        <button class="button button-secondary add-button" type="button" data-product-index="${index}">
          Add ${product.name} to cart
        </button>
      </div>
    </article>
  `;
}

function dealCardTemplate(product, index) {
  return `
    <article class="deal-card">
      <div class="product-art" style="--product-bg: ${product.art}" aria-hidden="true"></div>
      <div class="product-content">
        <span class="product-badge">${product.badge}</span>
        <h3>${product.name}</h3>
        <p>${product.description}</p>
        <div class="deal-price-row">
          <span class="deal-price">${product.price}</span>
          <span class="original-price">${product.originalPrice}</span>
        </div>
        <button class="button button-primary add-button" type="button" data-deal-index="${index}">
          Add ${product.name} to cart
        </button>
      </div>
    </article>
  `;
}

function renderProducts() {
  featuredContainer.innerHTML = featuredProducts.map(productCardTemplate).join("");
  dealsContainer.innerHTML = deals.map(dealCardTemplate).join("");
}

function updateCart(button) {
  const productName = button.dataset.productIndex
    ? featuredProducts[Number(button.dataset.productIndex)].name
    : deals[Number(button.dataset.dealIndex)].name;

  cartItems += 1;
  cartCount.textContent = String(cartItems);
  button.textContent = `Added ${productName} to cart`;
  window.setTimeout(() => {
    button.textContent = `Add ${productName} to cart`;
  }, 1400);
}

function toggleNav(forceOpen) {
  const shouldOpen = forceOpen ?? !navList.classList.contains("is-open");
  navList.classList.toggle("is-open", shouldOpen);
  navToggle.setAttribute("aria-expanded", String(shouldOpen));
  document.body.classList.toggle("nav-open", shouldOpen);
}

function setEmailError(message) {
  emailError.textContent = message;
  emailInput.setAttribute("aria-invalid", "true");
}

function clearEmailError() {
  emailError.textContent = "";
  emailInput.removeAttribute("aria-invalid");
}

renderProducts();

document.addEventListener("click", (event) => {
  const button = event.target.closest(".add-button");
  if (button) {
    updateCart(button);
  }
});

navToggle.addEventListener("click", () => {
  toggleNav();
});

navList.addEventListener("click", (event) => {
  if (event.target.matches("a")) {
    toggleNav(false);
  }
});

document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && navList.classList.contains("is-open")) {
    toggleNav(false);
    navToggle.focus();
  }
});

newsletterForm.addEventListener("submit", (event) => {
  event.preventDefault();
  formSuccess.textContent = "";

  if (!emailInput.validity.valid) {
    const message = emailInput.validity.valueMissing
      ? "Enter your email address to sign up."
      : "Enter an email address in the format name@example.com.";
    setEmailError(message);
    emailInput.focus();
    return;
  }

  clearEmailError();
  formSuccess.textContent = "Thanks. You are signed up for North & Finch updates.";
  newsletterForm.reset();
});

emailInput.addEventListener("input", () => {
  if (emailInput.validity.valid) {
    clearEmailError();
  }
  formSuccess.textContent = "";
});
